class DailyCrossAndRedStreakAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.pending_a = False
        self.pending_b = False

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        if self.IsWarmingUp:
            return

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        sma_today = self.spy_sma.Current.Value
        sma_yesterday = self.spy_sma.Previous.Value

        upward_cross = spy_close > sma_today and self.spy_sma.Previous.Value >= 0
        downward_cross = spy_close < sma_today and self.spy_sma.Previous.Value >= 0

        if self.strategy_a_lot > 0 and not self.pending_a and downward_cross:
            self.pending_a = True
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="Strategy A sell"
            )
        elif self.strategy_a_lot == 0 and not self.pending_a and upward_cross:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )

            if quantity > 0:
                self.pending_a = True
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A buy"
                )

        if self.strategy_b_lot > 0 and not self.pending_b:
            if self.aapl_rsi.Current.Value > 60:
                self.pending_b = True
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_lot,
                    tag="Strategy B sell"
                )
        elif self.strategy_b_lot == 0 and not self.pending_b:
            if self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(20000 / aapl_close)

                    if quantity > 0:
                        self.pending_b = True
                        self.MarketOrder(
                            self.aapl,
                            quantity,
                            tag="Strategy B buy"
                        )

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status != OrderStatus.Filled:
            if orderEvent.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]:
                if "Strategy A" in orderEvent.Tag:
                    self.pending_a = False
                elif "Strategy B" in orderEvent.Tag:
                    self.pending_b = False
            return

        quantity = orderEvent.FillQuantity

        if "Strategy A" in orderEvent.Tag:
            if quantity > 0:
                self.strategy_a_lot += quantity
            else:
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + quantity
                )

            if self.strategy_a_lot == 0 or quantity > 0:
                self.pending_a = False

        elif "Strategy B" in orderEvent.Tag:
            if quantity > 0:
                self.strategy_b_lot += quantity
            else:
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + quantity
                )

            if self.strategy_b_lot == 0 or quantity > 0:
                self.pending_b = False
